// Compile-Time Polymorphism (Template Metaprogramming / CRTP)
template <typename D>
struct ShapeCTP {
    void draw() { static_cast<D*>(this)->do_draw(); }
};
struct CircleCTP : ShapeCTP<CircleCTP> {
    void do_draw() {} // CTP: Zero runtime cost, resolved at compile time
};

// Runtime Polymorphism (Virtual Functions / VTable)
struct ShapeRTP {
    virtual void draw() = 0; // RTP: Adds vptr/vtable lookup overhead
};
struct CircleRTP : ShapeRTP {
    void draw() override {} // Dispatch occurs at runtime
};
